<?php

declare(strict_types=1);

use App\Http\AuthController;
use App\Http\Middleware\RequireAuth;
use Sahil\Http\Route;

/**
 * Authentication and dashboard pages, generated by `php sahil make:auth`.
 *
 * App\Providers\WebRoutesProvider loads this file when it exists, after
 * routes/web.php. The POST routes below are real: they validate the form,
 * call `AuthManager` / `PasswordResetManager`, and re-render with errors or
 * redirect on success. The dashboard requires an account.
 */
return [
    Route::get('/login', [AuthController::class, 'showLogin'])->name('auth.login'),
    Route::post('/login', [AuthController::class, 'login'])->name('auth.login.store'),

    Route::get('/register', [AuthController::class, 'showRegister'])->name('auth.register'),
    Route::post('/register', [AuthController::class, 'register'])->name('auth.register.store'),

    Route::get('/forgot-password', [AuthController::class, 'showForgotPassword'])->name('auth.password.request'),
    Route::post('/forgot-password', [AuthController::class, 'sendResetLink'])->name('auth.password.email'),

    Route::get('/reset-password/{token}', [AuthController::class, 'showResetPassword'])->name('auth.password.reset'),
    Route::post('/reset-password/{token}', [AuthController::class, 'resetPassword'])->name('auth.password.update'),

    Route::post('/logout', [AuthController::class, 'logout'])->name('auth.logout'),

    Route::get('/dashboard', [AuthController::class, 'showDashboard'])
        ->middleware(RequireAuth::class)
        ->name('dashboard'),
];
